"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60124"],{77394(e){e.exports=JSON.parse('{"id":"FIN-943","slug":"asset-light-business","term":"Asset-Light Business","also_known_as":[],"difficulty":"Intermediate","definition":"An asset-light business is a company that operates with relatively few physical assets, such as property, factories or equipment, often relying on outsourcing, partnerships, licensing or technology instead.","explanation":["Asset-light businesses aim to grow without large investments in fixed assets. They often own brands, technology, customer relationships or intellectual property rather than physical infrastructure.","Examples include hotel companies that manage or franchise hotels owned by others, ride-hailing platforms that do not own cars, online marketplaces that do not hold stock, and consumer brands that outsource manufacturing. For example, a hotel group might earn fees for managing hundreds of hotels and licensing its brand, while property investors own the buildings.","Asset-light models can generate high returns on capital, because the business needs less money tied up in assets. They can also grow faster, expand into new markets more easily and adapt more quickly to changes in demand.","The trade-offs include greater dependence on partners, less control over quality and operations, and sometimes lower barriers to entry, making it easier for competitors to copy the model. In downturns, asset-light companies have lower fixed costs, but they may also have fewer assets to fall back on. Asset-heavy businesses, such as utilities, airlines and manufacturers, are the opposite."],"note":"","total":1500,"prev":{"slug":"asset-heavy-business","term":"Asset-Heavy Business"},"next":{"slug":"asset-location","term":"Asset Location"}}')}}]);